package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class CommonMultipleListsTest {
 private List<String> solve(int a,int b){List<String> r=new ArrayList<>();for(int n=1;n<=100;n++)if(n/a*a==n&&n/b*b==n)r.add(""+n);return r;}
 @Test public void all78PublicPairsCheckCompleteListsAndNoneWithoutAnswerKeys(){Checker c=new Checker();int empty=0;for(int a=1;a<=12;a++)for(int b=a;b<=12;b++){Question q=CommonMultipleLists.make(a,b);List<String> solution=solve(a,b);q.answers=new String[]{"poison"};q.expression="poison";if(solution.isEmpty()){empty++;assertTrue(c.check(q,List.of(),List.of("",CommonMultipleLists.NONE)).correct());assertFalse(c.check(q,List.of(),List.of("100")).correct());}else{assertTrue(c.check(q,List.of(),solution).correct());assertFalse(c.check(q,List.of(),List.of(CommonMultipleLists.NONE)).correct());List<String> dup=new ArrayList<>(solution);dup.add(solution.get(solution.size()-1));assertEquals("중복된 수 확인",c.check(q,List.of(),dup).message);if(solution.size()>1)assertEquals("빠진 공배수 확인",c.check(q,List.of(),solution.subList(0,solution.size()-1)).message);for(int i=0;i<solution.size();i++){List<String> wrong=new ArrayList<>(solution);wrong.set(i,"101");assertEquals(i,c.check(q,List.of(),wrong).index);}}assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of(),List.of("" )).status);}assertEquals(2,empty);assertNull(CommonMultipleLists.read(new Question(CommonMultipleLists.ID,"12와 13의 공배수 중 100 이하인 양의 수를 모두 쓰세요.\n작은 수부터 쓰세요.","")));}
 @Test public void everyHelpUsesFirstPositiveMultipleAndPreservesNoneCases(){for(int a=1;a<=12;a++)for(int b=a;b<=12;b++){int first=1;while(first%a!=0||first%b!=0)first++;Question q=CommonMultipleLists.make(a,b);HelpPlan h=HelpPlan.forQuestion(q);assertFalse(h.canTransfer());assertTrue(h.restore(null,q.id).entries.stream().allMatch(String::isEmpty));assertTrue(h.step(0).accepts(""+first));assertTrue(h.step(1).accepts(""+(first/a)));assertTrue(h.step(2).accepts(""+(first/b)));assertTrue(h.step(3).accepts(first<=100?"1":"0"));assertEquals(first<=100?6:4,h.size());if(first<=100){assertTrue(h.step(4).accepts(""+(100/first)));assertTrue(h.step(5).accepts(""+(first*(100/first))));}}}
 @Test public void naturalGradeSixIncludesBothKindsAndFresh78BeforeOldest(){String pack="na-nied-primary-2024-v1";Learning.Profile p=new Learning.Profile();GlobalCurriculum.chooseCountry(p,"NA");GlobalCurriculum.choosePack(p,pack);assertTrue(GlobalCurriculum.pack(p).inGrade(CommonMultipleLists.ID,6));Generator gen=new Generator(new Random(263));CurriculumLimits l=GlobalCurriculum.limits(pack,CommonMultipleLists.ID,6);List<String> history=new ArrayList<>();int empty=0;for(int i=0;i<78;i++){Question q=gen.next(CommonMultipleLists.ID,history,false,l);assertFalse(history.contains(q.signature()));history.add(q.signature());assertTrue(gen.next(CommonMultipleLists.ID,List.of(),true,l).choices.isEmpty());int[] g=CommonMultipleLists.read(q);if(solve(g[0],g[1]).isEmpty())empty++;}assertEquals(2,empty);assertEquals(history.get(0),gen.next(CommonMultipleLists.ID,history,false,l).signature());assertFalse(Curriculum.inCurriculum(CommonMultipleLists.SKILL,2022));assertTrue(l.allows(CommonMultipleLists.make(10,11)));Question forged=CommonMultipleLists.make(3,5);forged.answers=new String[]{CommonMultipleLists.NONE};assertFalse(l.allows(forged));}
}
